// ─────────────────────────── индексы ───────────────────────────
const exact = new Map<string, OpeningInfo>();
const prefixes = new Set<string>();

for (const [eco, en, ru, moves] of ROWS) {
  const seq = moves.split(" ");
  exact.set(seq.join(" "), { eco, en, ru });
  for (let i = 1; i <= seq.length; i++) prefixes.add(seq.slice(0, i).join(" "));
}

export function openingForCode(code: string): OpeningInfo | undefined {
  const c = code.toUpperCase().trim();
  if (!/^[A-E]\d\d$/.test(c)) return undefined;
  for (const o of exact.values()) if (o.eco === c) return o;
  for (const [a, b, en, ru] of FAMILIES) if (c >= a && c <= b) return { eco: c, en, ru };
  return undefined;
}

export interface BookInfo {
  isBook: boolean[];
  opening: (OpeningInfo | undefined)[]; // для каждого полухода — самое глубокое названное совпадение
  last?: OpeningInfo;
}

/** Размечает книжные ходы по списку SAN (без символов +/#). */
export function analyzeBook(sans: string[]): BookInfo {
  const clean = sans.map((s) => s.replace(/[+#!?]/g, ""));
  const isBook: boolean[] = [];
  const opening: (OpeningInfo | undefined)[] = [];
  let cur: OpeningInfo | undefined;
  let inBook = true;
  for (let i = 0; i < clean.length; i++) {
    const key = clean.slice(0, i + 1).join(" ");
    if (inBook && prefixes.has(key)) {
      isBook.push(true);
      const e = exact.get(key);
      if (e) cur = e;
    } else {
      inBook = false;
      isBook.push(false);
    }
    opening.push(cur);
  }
  return { isBook, opening, last: cur };
}
